"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[930],{52812:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"StockData","desc":"Limited-stock behavior for a shop item. Absent from an item means unlimited stock.","fields":[{"name":"maxStockQuantity","lua_type":"number","desc":"The maximum number of items that can be in stock"},{"name":"restockInterval","lua_type":"number","desc":"Seconds between full restocks"}],"source":{"line":37,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"BaseItem","desc":"The fields every item shares, regardless of what kind of item it is.","fields":[{"name":"name","lua_type":"string","desc":"Display name shown in the shop and inventory"},{"name":"description","lua_type":"string?","desc":"Blurb shown on the item\'s detail card"},{"name":"type","lua_type":"string","desc":"Item category (`\\"Skin\\"`, `\\"Emote\\"`, `\\"Pet\\"`, ...)"},{"name":"subtype","lua_type":"string?","desc":"If the item is a subtype of another item"},{"name":"icon","lua_type":"string?","desc":"A placeholder icon is used if not defined"},{"name":"purchasePrice","lua_type":"number?","desc":"Cost to buy; absent means not purchasable"},{"name":"purchaseCurrency","lua_type":"string?","desc":"Defaults to `\\"Coins\\"` when `purchasePrice` is set"},{"name":"hidden","lua_type":"boolean?","desc":"Kept out of shop listings"},{"name":"rarity","lua_type":"string?","desc":"Rarity key, see `RarityData.Rarity`"},{"name":"resaleValue","lua_type":"number?","desc":"Item cannot be sold without this field"},{"name":"cameraOffset","lua_type":"CFrame?","desc":"Viewport CFrame offset when shown in a ViewportFrame"},{"name":"maxCopies","lua_type":"number?","desc":"Nil means the item can be purchased infinitely"},{"name":"model","lua_type":"Model?","desc":"Source model cloned when the item is spawned"},{"name":"levelRequirement","lua_type":"number?","desc":"Player level needed to purchase"},{"name":"townLevelRequirement","lua_type":"number?","desc":"Town level needed to purchase"},{"name":"stockData","lua_type":"StockData?","desc":"Limited-stock config; absent means unlimited"},{"name":"props","lua_type":"{ [string]: any }?","desc":"Extra properties that don\'t warrant their own field"},{"name":"ownershipLimit","lua_type":"number?","desc":"Max quantity a player can own of this item"},{"name":"boxes","lua_type":"{ string }?","desc":"Loot box ids this item\'s pool belongs to; see BoxService"}],"source":{"line":67,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"PropUpgradeInfo","desc":"One entry in a prop\'s `upgrades` list. A prop\'s level is its index into that\\nlist \u2014 props start at level 1, and buying the upgrade at index *n* moves them to\\nlevel *n + 1*.","fields":[{"name":"name","lua_type":"string?","desc":"Display name of the upgrade"},{"name":"description","lua_type":"string?","desc":"Blurb shown on the upgrade prompt"},{"name":"purchasePrice","lua_type":"number","desc":"Cost to apply this upgrade"},{"name":"purchaseCurrency","lua_type":"string?","desc":"Defaults to `\\"Coins\\"` when `purchasePrice` is set"},{"name":"townLevelRequirement","lua_type":"number?","desc":"Town level needed to purchase the upgrade"},{"name":"icon","lua_type":"string?","desc":""},{"name":"buildTime","lua_type":"number?","desc":"Seconds the upgrade takes to build"},{"name":"props","lua_type":"{ [string]: any }?","desc":"Extra properties that don\'t warrant their own field"}],"source":{"line":106,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"PropItem","desc":"A [BaseItem] that can be placed on a base.\\n\\nThis type exists to make the shape easier to read while authoring prop item\\ndata, where several BaseItem fields are still optional. Use [PropItemData]\\neverywhere else.\\n\\nRemoving a prop requires meeting the same gates as buying it \u2014\\n`levelRequirement`, `townLevelRequirement`, `purchasePrice` and so on.\\n\\n`propDisplayPaths` entries are paths relative to the data\'s `props` table. Lookup\\nwalks the current level\'s upgrade info down to level 1 for a value; if the next\\nlevel also defines that path, the display shows `\\"currentValue -> nextValue\\"`.\\n\\n:::note destructionPrice is inert\\nThe `destructionPrice` field and the [FeatureFlags].ChargeForDestruction flag\\nthat would govern it both exist, but nothing in the codebase currently reads\\neither one. Removing a prop is free today.\\n:::","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":"Required for props, unlike on BaseItem"},{"name":"buildTime","lua_type":"number?","desc":"Seconds the prop takes to build"},{"name":"upgrades","lua_type":"{ PropUpgradeInfo }?","desc":"Levels this prop can be upgraded through"},{"name":"useUpgradePrompt","lua_type":"boolean?","desc":"Show the upgrade prompt when a player is nearby"},{"name":"immovable","lua_type":"boolean?","desc":"Disables the move tool for this prop"},{"name":"destructionPrice","lua_type":"number?","desc":"Cost to remove the prop, if set"},{"name":"destroyTime","lua_type":"number?","desc":"Seconds the prop takes to destroy"},{"name":"stashable","lua_type":"boolean?","desc":"Prop can be stashed back into the player\'s inventory"},{"name":"propDisplayPaths","lua_type":"{ { path: string, label: string, formatter: ((any) -> string)? } }?","desc":"Stats surfaced on the nearby-prop display"}],"source":{"line":149,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"PropItemData","desc":"[PropItem] with its defaults filled in. This is the type to consume outside\\nof item data \u2014 the optional fields are guaranteed here.","fields":[{"name":"purchasePrice","lua_type":"number","desc":"Defaults to 0"},{"name":"levelRequirement","lua_type":"number","desc":"Defaults to 0"},{"name":"ownershipLimit","lua_type":"number","desc":"Max owned including placed props; enforced on purchase only"},{"name":"model","lua_type":"Model","desc":"Always present once the registry has resolved it"}],"source":{"line":193,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"SeedItemData","desc":"A plantable seed and its growth timings.\\n\\nSupplying `cropTreeData` turns the seed into a crop *tree*: instead of being\\nharvested once, it repeatedly yields produce every `produceGrowTime` seconds,\\nindefinitely unless `produceYield` caps it.","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":""},{"name":"seedTime","lua_type":"number?","desc":"Seconds from seed to flower (usually within seconds)"},{"name":"maturityTime","lua_type":"number","desc":"Seconds until the crop is ready to harvest"},{"name":"floweringTime","lua_type":"number?","desc":"Seconds; must be less than `maturityTime`, defaults to half of it"},{"name":"harvestTime","lua_type":"number?","desc":"Seconds after maturity before withering; absent means it never withers"},{"name":"cropItemId","lua_type":"string","desc":"Id of the crop this seed grows into"},{"name":"cropTreeData","lua_type":"{ produceGrowTime: number, produceYield: number? }?","desc":"Present only for tree crops"}],"source":{"line":230,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"SkinSurfaceAppearance","desc":"PBR map set baked onto the default skin mesh via a SurfaceAppearance child.\\n\\nA mesh-swap cosmetic skin has three visual paths, in order of precedence:\\n\\n1. Hand-authored MeshPart at `ReplicatedStorage.Assets.Cosmetics.<itemId>`\\n   (escape hatch for skins with custom geometry).\\n2. `surfaceAppearance` \u2014 this type. Use for metals, gems, glossy looks.\\n3. `texture` \u2014 a single image asset id set as the MeshPart\'s `TextureID`.\\n   Use for plain painted/diffuse looks.\\n\\nBoth (2) and (3) are baked into `assets/shared/Cosmetics.rbxm` by the Lune build\\ntool; SurfaceAppearance can\'t be assigned at runtime.","fields":[{"name":"ColorMap","lua_type":"string?","desc":""},{"name":"MetalnessMap","lua_type":"string?","desc":""},{"name":"RoughnessMap","lua_type":"string?","desc":""},{"name":"NormalMap","lua_type":"string?","desc":""}],"source":{"line":282,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"SkinItem","desc":"A mesh-swap cosmetic skin, or a gear skin when `subtype` names a gear slot. See\\nthe comment on [SkinSurfaceAppearance] for the three visual paths and their\\norder of precedence; gear skins instead take their model from\\n`Assets.Cosmetics.<itemId>` and may override the gear config through `gear`.","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":""},{"name":"surfaceAppearance","lua_type":"SkinSurfaceAppearance?","desc":"PBR map set (precedence 2)"},{"name":"texture","lua_type":"string?","desc":"Single diffuse image asset id (precedence 3)"},{"name":"particles","lua_type":"{ ParticleEmitterConfig }?","desc":"Emitters baked under the skin\'s MeshPart"},{"name":"gear","lua_type":"Gearkit.GearOverride?","desc":"Gear skins only: config deep-merged over the base gear"}],"source":{"line":351,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"KillEffectBurst","desc":"A one-shot particle burst every client plays at the victim\'s position.","fields":[{"name":"texture","lua_type":"string","desc":"Particle texture (`rbxasset://` or `rbxassetid://`)"},{"name":"color","lua_type":"Color3","desc":""},{"name":"count","lua_type":"number","desc":"Particles emitted in the one-shot burst"},{"name":"size","lua_type":"number?","desc":"Starting particle size in studs; 0.6 when nil"},{"name":"acceleration","lua_type":"Vector3?","desc":"Constant pull on the particles, e.g. upward drift"},{"name":"lightEmission","lua_type":"number?","desc":"1 (default) glows additively; 0 keeps solid sprites solid"}],"source":{"line":373,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"KillEffectItem","desc":"A cosmetic VFX played on the victim when a kill lands.","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":""},{"name":"burst","lua_type":"KillEffectBurst?","desc":"Plays nothing when absent"}],"source":{"line":390,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"EmoteItem","desc":"An emote the owner plays from the lobby (see `EmoteController`).","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":""},{"name":"animation","lua_type":"string?","desc":"Animation asset id played on the owner\'s Animator"}],"source":{"line":405,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"PetItem","desc":"A cosmetic follower that trails its owner (see `PetController`).","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":""},{"name":"template","lua_type":"string?","desc":"Model path under `ReplicatedStorage.Assets`, dot-separated"},{"name":"flying","lua_type":"boolean?","desc":"Hovers beside the owner instead of walking behind"}],"source":{"line":422,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"TitleItem","desc":"A title shown before the player\'s name in chat and above it overhead. A\\nmoving gradient must loop (first color = last) to scroll seamlessly.","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":""},{"name":"text","lua_type":"string?","desc":"Display text; falls back to `name`"},{"name":"gradient","lua_type":"ColorSequence?","desc":"Colors the text instead of the rarity color"},{"name":"gradientSpeed","lua_type":"number?","desc":"Gradient loops per second overhead; static when nil"}],"source":{"line":441,"path":"src/Shared/Types/ItemTypes.luau"}},{"name":"NametagItem","desc":"An effect applied to the player\'s DisplayName (gradient, glow, shimmer...),\\nboth over their head and in chat.","fields":[{"name":"rarity","lua_type":"RarityData.Rarity","desc":""},{"name":"gradient","lua_type":"ColorSequence?","desc":"Colors across the name, left to right"}],"source":{"line":459,"path":"src/Shared/Types/ItemTypes.luau"}}],"name":"ItemTypes","desc":"Shared shape of everything the game treats as an \\"item\\": shop stock, inventory\\nrecords, placeable props, seeds and crops, animals, and cosmetic skins.\\n\\nEvery item type starts from [BaseItem] and intersects extra fields onto it, so a\\nfield documented on BaseItem means the same thing everywhere. Concrete item tables\\nlive in the `src/Shared/Data/Items/` and `src/Shared/Data/Cosmetics/` registries\\nand are keyed by item id; those registries are what the shop and inventory read\\nat runtime. The prop, seed, crop, animal and egg shapes only type the flag-gated\\nBase classes; no items of those kinds ship in the registries.\\n\\nThe `*ItemData` variants exist to tighten optional BaseItem fields into required\\nones once the registry has filled in defaults \u2014 author data against [PropItem],\\nconsume it as [PropItemData].\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":21,"path":"src/Shared/Types/ItemTypes.luau"}}')}}]);